<template><AppLayout><TablePageLayout><template #filters><div><h1 class="text-xl font-semibold">{{ t('marketplace.statements') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('marketplace.statementTimezone') }}</p><p v-if="error" role="alert" class="mt-2 text-sm text-red-700">{{ error }} <button class="underline" @click="load(page)">{{ t('marketplace.retry') }}</button></p></div></template><template #table><DataTable :columns="columns" :data="items" :loading="loading" row-key="id"><template #empty><p class="p-6 text-sm text-gray-500">{{ t('marketplace.noStatements') }}</p></template><template #cell-actions="{ row }"><button data-test="statement-detail" class="text-primary-600 underline" @click="detail(row.id)">{{ t('marketplace.details') }}</button> <button class="ml-2 text-primary-600 underline" @click="download(row.id)">{{ t('marketplace.downloadCsv') }}</button></template></DataTable></template><template #pagination><Pagination v-if="total > 0" :page="page" :page-size="20" :show-page-size-selector="false" :total="total" @update:page="load" /></template></TablePageLayout>
<BaseDialog :show="!!selected" :title="t('marketplace.statementDetails')" @close="selected = null"><template v-if="selected"><p class="mb-4 text-sm text-gray-500">{{ selected.month }} · {{ t('marketplace.version') }} {{ selected.version }} · {{ selected.currency }} · {{ t('marketplace.cutoffLedger') }} {{ selected.cutoff_ledger_id }}</p><dl class="grid grid-cols-2 gap-4 sm:grid-cols-3"><div v-for="field in fields" :key="field"><dt class="text-sm text-gray-500">{{ t('marketplace.' + field) }}</dt><dd class="font-medium tabular-nums">{{ selected[field] ?? '—' }}</dd></div></dl><h4 class="mt-6 font-semibold">{{ t('marketplace.statementEntries') }}</h4><p v-if="entryError" role="alert" class="mt-3 text-sm text-red-700">{{ entryError }} <button class="underline" @click="loadEntries(entryPage)">{{ t('marketplace.retry') }}</button></p><p v-else-if="entryLoading" class="mt-3 text-sm">{{ t('marketplace.loading') }}</p><p v-else-if="!entries.length" class="mt-3 text-sm text-gray-500">{{ t('marketplace.noStatementEntries') }}</p><div v-else class="mt-3 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>{{ t('marketplace.date') }}</th><th>{{ t('marketplace.accountName') }}</th><th>{{ t('marketplace.model') }}</th><th>{{ t('marketplace.status') }}</th><th>{{ t('marketplace.consumerCharge') }}</th><th>{{ t('marketplace.platformFee') }}</th><th>{{ t('marketplace.supplierNet') }}</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.operation_id" class="border-t dark:border-dark-600"><td class="py-2">{{ entry.date }}<div class="text-xs">{{ entry.operation_id }}</div></td><td>{{ entry.account_name }}</td><td>{{ entry.model }}</td><td>{{ entry.kind === 'refund' ? t('marketplace.entryRefund') : entry.kind === 'capture' ? t('marketplace.entryCapture') : entry.kind }}</td><td>{{ entry.consumer_charge }}</td><td>{{ entry.platform_fee }}</td><td>{{ entry.supplier_net }}</td></tr></tbody></table></div><div v-if="entryPages > 1" class="mt-3 flex items-center gap-3"><button class="btn btn-secondary btn-sm" :disabled="entryLoading || entryPage <= 1" @click="loadEntries(entryPage - 1)">{{ t('marketplace.previous') }}</button><span>{{ entryPage }} / {{ entryPages }}</span><button class="btn btn-secondary btn-sm" :disabled="entryLoading || entryPage >= entryPages" @click="loadEntries(entryPage + 1)">{{ t('marketplace.next') }}</button></div></template></BaseDialog></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TablePageLayout from '@/components/layout/TablePageLayout.vue'
import DataTable from '@/components/common/DataTable.vue'
import Pagination from '@/components/common/Pagination.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import { listStatements, getStatement, exportStatement, listStatementEntries } from '@/api/supplier'
import type { SupplierStatement, StatementEntry } from '@/types/marketplace'
const { t } = useI18n(); const items = ref<SupplierStatement[]>([]); const selected = ref<SupplierStatement | null>(null); const page = ref(1); const total = ref(0); const loading = ref(false); const error = ref('')
const columns = computed(() => [{ key: 'month', label: t('marketplace.month') }, { key: 'version', label: t('marketplace.version') }, { key: 'earned_net', label: t('marketplace.earnedNet') }, { key: 'refund_net', label: t('marketplace.refundAmount') }, { key: 'payout_paid', label: t('marketplace.payoutPaid') }, { key: 'actions', label: t('marketplace.actions') }])
const entries = ref<StatementEntry[]>([]); const entryPage = ref(1); const entryPages = ref(0); const entryLoading = ref(false); const entryError = ref('')
const fields = ['opening_pending', 'opening_available', 'opening_reserved', 'closing_pending', 'closing_available', 'closing_reserved', 'earned_net', 'platform_fee', 'refund_net', 'payout_paid'] as const
async function load(next = 1) { loading.value = true; error.value = ''; try { const result = await listStatements(next); items.value = result.items; page.value = result.page; total.value = result.total } catch { error.value = t('marketplace.loadFailed') } finally { loading.value = false } }
async function detail(id: number) { selected.value = null; entries.value = []; entryError.value = ''; try { selected.value = await getStatement(id); await loadEntries(1) } catch { error.value = t('marketplace.loadFailed') } }
async function loadEntries(next: number) { if (!selected.value) return; entryLoading.value = true; entryError.value = ''; try { const result = await listStatementEntries(selected.value.id, next); entries.value = result.items; entryPage.value = result.page; entryPages.value = result.pages } catch { entries.value = []; entryError.value = t('marketplace.loadFailed') } finally { entryLoading.value = false } }
async function download(id: number) { try { const blob = await exportStatement(id); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `statement-${id}.csv`; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url) } catch { error.value = t('marketplace.exportFailed') } }
onMounted(() => load())
</script>
